10	)
11	
12	// readStatus reads the state and the starttime of pid from /proc/<pid>/stat,
13	// in one read. A PID with no process reads as os.ErrProcessDone. A zombie still
14	// has a stat file, with state Z and its starttime kept (proc(5)); a Z leader
15	// whose other threads still run is alive, which the thread count tells.
16	func readStatus(pid int) (procStatus, error) {
17		path := "/proc/" + strconv.Itoa(pid) + "/stat"
18		data, err := os.ReadFile(path)
19		if err != nil {
20			if errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ESRCH) {
21				return procStatus{}, fmt.Errorf("reading %s: %w", path, os.ErrProcessDone)
22			}
23			return procStatus{}, err
24		}
25		state, start, err := parseStat(data)
26		if err != nil {
27			return procStatus{}, err
28		}
29		threads := 0 // unknown counts as alive (isLinuxZombie)
30		if state == 'Z' {
31			threads, err = readThreads(pid)
32			if errors.Is(err, os.ErrProcessDone) {
33				return procStatus{}, err
34			}
35			// Any other error leaves threads at 0: the process reads as running.
36		}
37		return procStatus{start: start, zombie: isLinuxZombie(state, threads)}, nil
38	}
39	
40	// readThreads reads the thread count of pid from /proc/<pid>/status. It is asked
41	// only for a process whose stat says Z, to tell a zombie (one thread left, the
42	// leader) from a live process whose main thread has exited.
43	func readThreads(pid int) (int, error) {
44		path := "/proc/" + strconv.Itoa(pid) + "/status"
45		data, err := os.ReadFile(path)
46		if err != nil {
47			if errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ESRCH) {
48				return 0, fmt.Errorf("reading %s: %w", path, os.ErrProcessDone)
49			}
50			return 0, err
51		}
52		return parseThreads(data)
53	}
54	
55	// readIdentity reads the starttime of pid.
56	func readIdentity(pid int) (uint64, error) {
57		st, err := readStatus(pid)
58		return st.start, err
59	}
60	
61	// heldIdentity reads the identity while p holds the process. On Linux 5.4 and
62	// later os.FindProcess opened a pidfd, so a PID reused after that cannot receive
63	// the signal: the stamp read here belongs to the PID's holder at this instant,
64	// which is p's process or a newcomer, and a newcomer reads as another stamp.
65	func heldIdentity(_ *os.Process, pid int) (uint64, error) { return readIdentity(pid) }
66	
67	// isNoSuchProcess never holds on Linux: os.FindProcess does not fail there.
68	func isNoSuchProcess(error) bool { return false }
